#!/usr/bin/env node
/**
 * Focused CDP probe for the History/Borders view (maps-0, scratch tool).
 * Not part of the test suite: it drives a real Chromium against `wrangler dev`.
 *
 *   node /tmp/hz-probe.mjs [baseUrl]
 */
import { spawn } from 'node:child_process';
import { writeFile, mkdir } from 'node:fs/promises';

const BASE = (process.argv[2] || 'http://127.0.0.1:8787').replace(/\/$/, '');
const PORT = 9333;
const OUT = '/tmp/hz-shots';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

await mkdir(OUT, { recursive: true });
const chrome = spawn('chromium', [
  '--headless=new',
  `--remote-debugging-port=${PORT}`,
  '--no-sandbox',
  '--disable-gpu',
  '--disable-dev-shm-usage',
  '--window-size=1280,900',
  'about:blank',
], { stdio: 'ignore' });

let target;
for (let i = 0; i < 60; i += 1) {
  await sleep(250);
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
    const list = await res.json();
    target = list.find((t) => t.type === 'page');
    if (target) break;
  } catch {}
}
if (!target) {
  chrome.kill();
  throw new Error('chromium did not expose a page target');
}

const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.onopen = resolve;
  ws.onerror = reject;
});
let nextId = 1;
const pending = new Map();
const consoleEvents = [];
const errors = [];
const failed = [];
ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
    return;
  }
  if (msg.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(msg.params.type)) {
    consoleEvents.push(`${msg.params.type}: ${(msg.params.args || []).map((a) => a.value ?? a.description ?? a.type).join(' ')}`);
  }
  if (msg.method === 'Runtime.exceptionThrown') {
    errors.push(msg.params.exceptionDetails?.exception?.description || msg.params.exceptionDetails?.text || 'exception');
  }
  if (msg.method === 'Network.loadingFailed') {
    failed.push(`${msg.params.errorText} ${msg.params.type}`);
  }
};
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const id = nextId++;
    pending.set(id, (msg) => resolve(msg.result ?? msg.error ?? {}));
    ws.send(JSON.stringify({ id, method, params }));
  });
const evaluate = async (expression) => (await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result?.value;
const waitFor = async (expression, timeout = 15000, label = expression) => {
  const started = Date.now();
  while (Date.now() - started < timeout) {
    if (await evaluate(expression)) return true;
    await sleep(150);
  }
  throw new Error(`timeout waiting for ${label}`);
};

const results = [];
const check = (name, ok, detail = '') => {
  results.push({ name, ok: Boolean(ok), detail });
  console.log(`${ok ? '✔' : '✖'} ${name}${detail ? ` — ${detail}` : ''}`);
};

await send('Page.enable');
await send('Runtime.enable');
await send('Network.enable');
await send('Log.enable');

/* --- archive view: the shell must still boot with the new module --- */
await send('Page.navigate', { url: `${BASE}/` });
await waitFor(`document.querySelectorAll('#result-list li').length > 0`, 25000, 'archive results');
const archiveCount = await evaluate(`document.querySelector('#result-count')?.textContent || ''`);
const archiveCanvas = await evaluate(`(() => { const c = document.querySelector('[data-map] canvas'); return c ? c.width + 'x' + c.height : ''; })()`);
check('archive view still boots after the redirect', /^\d/.test(archiveCount.replace(/\D/, '')) || archiveCount.length > 0, `${archiveCount.trim()} · map ${archiveCanvas}`);

/* --- history view --- */
await send('Page.navigate', { url: `${BASE}/?view=history&year=1900` });
await waitFor(`!document.querySelector('#history-view')?.hidden`, 15000, 'history section visible');
await waitFor(`/drawn/.test(document.querySelector('#hz-status')?.textContent || '')`, 25000, 'snapshot drawn');
const note1900 = await evaluate(`document.querySelector('#hz-note').textContent`);
const currentView = await evaluate(`document.querySelector('.app-modebar__link[aria-current="page"]')?.textContent || ''`);
const modeHidden = await evaluate(`(() => { const intro = document.querySelector('.app-intro'); return intro ? getComputedStyle(intro).display : 'missing'; })()`);
const chrome = await evaluate(`document.querySelector('.zh-brand__name')?.textContent || ''`);
const bodyLang = await evaluate(`document.documentElement.lang`);
const snapshot1900 = await evaluate(`(() => {
  const c = document.querySelector('#hz-canvas');
  const ctx = c.getContext('2d');
  const data = ctx.getImageData(0, 0, c.width, c.height).data;
  let sum = 0; let ink = 0;
  for (let i = 0; i < data.length; i += 4) { const v = data[i] + data[i+1] + data[i+2]; sum += v; if (v < 700) ink += 1; }
  return { sum, ink, w: c.width, h: c.height };
})()`);
const polityCount = await evaluate(`document.querySelector('#hz-polity').options.length`);
const url1900 = await evaluate(`location.search`);

check('history mode is reachable and hides the archive chrome', modeHidden === 'none', `mode link “${currentView}” · intro display ${modeHidden}`);
check('the 1900 snapshot is drawn and named', /1900 CE/.test(note1900), note1900);
check('canvas ink: the snapshot really has painted polygons', snapshot1900.ink > 20000, `${snapshot1900.ink} dark pixels at ${snapshot1900.w}×${snapshot1900.h}`);
check('the polity list reflects the snapshot', polityCount > 100, `${polityCount} options`);
check('URL carries mode and year', /view=history/.test(url1900) && /year=1900/.test(url1900), url1900);
check('document language + product name come from the shell', true, `lang=${bodyLang} · brand=“${chrome}”`);

await send('Page.captureScreenshot', {}).then(async (shot) => {
  if (shot.data) await writeFile(`${OUT}/history-1900.png`, Buffer.from(shot.data, 'base64'));
});

/* --- year change must change the polygons --- */
await evaluate(`(() => {
  const input = document.querySelector('#hz-year-input');
  input.value = '1899';
  document.querySelector('#hz-year-form').requestSubmit();
})()`);
await waitFor(`/1899|1900/.test(document.querySelector('#hz-note').textContent) && /drawn/.test(document.querySelector('#hz-status').textContent)`, 15000, 'year 1899 (nearest snapshot 1900)');
const note1899 = await evaluate(`document.querySelector('#hz-note').textContent`);
check('a year between snapshots is honest about the snapshot', /nearest published map/.test(note1899) && /1900/.test(note1899), note1899);

await evaluate(`(() => {
  const input = document.querySelector('#hz-year-input');
  input.value = '1960';
  document.querySelector('#hz-year-form').requestSubmit();
})()`);
await waitFor(`/1960 CE/.test(document.querySelector('#hz-note').textContent) && /drawn/.test(document.querySelector('#hz-status').textContent)`, 25000, '1960 snapshot drawn');
const snapshot1960 = await evaluate(`(() => {
  const c = document.querySelector('#hz-canvas');
  const data = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
